import React from 'react';
import { motion } from 'framer-motion';

const Skills = () => {
  const skills = [
    {
      icon: 'fab fa-js text-4xl text-yellow-400',
      title: 'Vanilla JavaScript',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    },
    {
      icon: 'flex space-x-2 text-4xl',
      icons: [
        'fab fa-angular text-red-600',
        'fab fa-react text-blue-400',
        'fab fa-vuejs text-green-500'
      ],
      title: 'Angular, React & Vue',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    },
    {
      icon: 'fab fa-node text-4xl text-green-600',
      title: 'Node.js',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    },
    {
      icon: 'fab fa-python text-4xl text-blue-500',
      title: 'Python & Django',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    },
    {
      icon: 'fab fa-php text-4xl text-indigo-500',
      title: 'PHP',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    },
    {
      icon: 'flex space-x-2 text-4xl',
      icons: [
        'fab fa-npm text-red-500',
        'fas fa-gulp text-red-400',
        'fab fa-grunt text-orange-400'
      ],
      title: 'npm, Gulp & Grunt',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    },
    {
      icon: 'flex space-x-2 text-4xl',
      icons: [
        'fab fa-html5 text-orange-500',
        'fab fa-css3-alt text-blue-600'
      ],
      title: 'HTML & CSS',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    },
    {
      icon: 'flex space-x-2 text-4xl',
      icons: [
        'fab fa-sass text-pink-500',
        'fab fa-less text-blue-800'
      ],
      title: 'Sass & LESS',
      description: 'List skills/technologies here. You can change the icon above to any of the 1500+ FontAwesome 5 free icons available. Aenean commodo ligula eget dolor.'
    }
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.5
      }
    }
  };

  return (
    <motion.section
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, amount: 0.3 }}
      variants={containerVariants}
    >
      <motion.div
        variants={itemVariants}
        className="border-l-4 border-primary pl-4 mb-6"
      >
        <h2 className="text-3xl font-bold text-gray-900 dark:text-white">
          What I do
        </h2>
      </motion.div>
      <motion.p
        variants={itemVariants}
        className="text-gray-600 dark:text-gray-300 mb-12 max-w-4xl leading-relaxed"
      >
        I have more than 10 years' experience building software for clients
        all over the world. Below is a quick overview of my main technical
        skill sets and technologies I use. Want to find out more about my
        experience? Check out my{' '}
        <a className="text-primary hover:underline" href="#">online resume</a>
        {' '}and{' '}
        <a className="text-primary hover:underline" href="#">
          project portfolio
        </a>
        .
      </motion.p>
      <motion.div
        variants={containerVariants}
        className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-x-8 gap-y-12"
      >
        {skills.map((skill, index) => (
          <motion.div
            key={index}
            variants={itemVariants}
            whileHover={{ y: -5, scale: 1.02 }}
            className="space-y-3"
          >
            <motion.div
              whileHover={{ scale: 1.1 }}
              transition={{ type: "spring", stiffness: 400 }}
            >
              {skill.icons ? (
                <div className={skill.icon}>
                  {skill.icons.map((iconClass, iconIndex) => (
                    <i key={iconIndex} className={iconClass}></i>
                  ))}
                </div>
              ) : (
                <i className={skill.icon}></i>
              )}
            </motion.div>
            <h3 className="font-bold text-lg text-gray-800 dark:text-white">
              {skill.title}
            </h3>
            <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed">
              {skill.description}
            </p>
          </motion.div>
        ))}
      </motion.div>
    </motion.section>
  );
};

export default Skills;
